def rotate_items(items, k):
    if isinstance(k, bool) or not isinstance(k, int) or k < 0:
        raise ValueError("k must be a nonnegative integer")

    items = tuple(items)
    if not items:
        return ()

    shift = k % len(items)
    if shift == 0:
        return items
    return items[-shift:] + items[:-shift]

def interleave(left, right):
    if len(left) != len(right):
        raise ValueError("left and right must have the same length")

    result = []
    for left_item, right_item in zip(left, right):
        result.extend((left_item, right_item))
    return tuple(result)

def sort_labels(labels):
    if labels is None:
        raise ValueError("labels must be an iterable of strings")

    distinct = {}
    for label in labels:
        if not isinstance(label, str):
            raise TypeError("labels must contain only strings")
        key = label.casefold()
        if key not in distinct:
            distinct[key] = label

    return tuple(distinct[key] for key in sorted(distinct))

def find_products(products, query):
    from decimal import Decimal
    from numbers import Real

    if not isinstance(query, str):
        raise TypeError("query must be a string")
    if products is None or isinstance(products, (str, bytes)):
        raise TypeError("products must be an iterable of dictionaries")

    try:
        product_items = tuple(products)
    except TypeError as exc:
        raise TypeError("products must be an iterable of dictionaries") from exc

    query_text = query.casefold()
    matches = []

    for product in product_items:
        if not isinstance(product, dict):
            raise TypeError("each product must be a dictionary")
        if "name" not in product or "score" not in product:
            raise ValueError("each product must have a name and score")

        name = product["name"]
        score = product["score"]

        if not isinstance(name, str):
            raise TypeError("product names must be strings")
        if isinstance(score, bool) or not isinstance(score, (Real, Decimal)):
            raise TypeError("product scores must be numeric")

        if query_text in name.casefold():
            matches.append(product)

    matches.sort(key=lambda product: product["score"], reverse=True)
    return tuple(matches)

def group_words(words):
    if isinstance(words, str):
        raise TypeError("words must be an iterable of strings, not a string")

    groups = {}
    normalized_keys = {}

    for word in words:
        if not isinstance(word, str):
            raise TypeError("each word must be a string")
        if not word:
            raise ValueError("words must not be empty")

        initial = word[0]
        normalized = initial.casefold()

        if normalized not in normalized_keys:
            normalized_keys[normalized] = initial
            groups[initial] = []

        groups[normalized_keys[normalized]].append(word)

    return {initial: tuple(group) for initial, group in groups.items()}

def parse_integer_fields(fields):
    if isinstance(fields, (str, bytes, bytearray)):
        raise TypeError("fields must be a sequence of strings")

    values = []
    for field in fields:
        if not isinstance(field, str):
            raise TypeError("each field must be a string")
        values.append(int(field))

    return tuple(values)

def nearest_date(dates, target):
    from datetime import date

    def parse_iso_date(value):
        if not isinstance(value, str):
            raise TypeError("dates must be strings")
        if (
            len(value) != 10
            or value[4] != "-"
            or value[7] != "-"
            or any(not ("0" <= char <= "9") for i, char in enumerate(value) if i not in (4, 7))
        ):
            raise ValueError("dates must use YYYY-MM-DD format")
        try:
            parsed = date.fromisoformat(value)
        except ValueError:
            raise ValueError("invalid calendar date") from None
        if parsed.isoformat() != value:
            raise ValueError("dates must use YYYY-MM-DD format")
        return parsed

    target_date = parse_iso_date(target)
    closest_value = None
    closest_distance = None

    for value in dates:
        current_date = parse_iso_date(value)
        distance = abs((current_date - target_date).days)
        if closest_distance is None or distance < closest_distance:
            closest_value = value
            closest_distance = distance

    return closest_value

def median_value(values):
    ordered = sorted(values)
    if not ordered:
        return None

    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]

    return (ordered[middle - 1] + ordered[middle]) / 2

def merge_ranges(ranges):
    intervals = []
    for interval in ranges:
        start, end = interval
        if start > end:
            raise ValueError("range start must not exceed its end")
        intervals.append((start, end))

    intervals.sort(key=lambda interval: interval[0])

    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    return tuple(merged)

def shortest_path(graph, start, goal):
    from collections import deque
    from collections.abc import Mapping

    if not isinstance(graph, Mapping):
        raise TypeError("graph must be a mapping")

    hash(start)
    hash(goal)

    if start == goal:
        return (start,)

    parents = {start: None}
    queue = deque([start])

    while queue:
        node = queue.popleft()
        for neighbor in graph.get(node, ()):
            if neighbor in parents:
                continue
            parents[neighbor] = node
            if neighbor == goal:
                path = []
                current = goal
                while current is not None:
                    path.append(current)
                    current = parents[current]
                return tuple(reversed(path))
            queue.append(neighbor)

    return None

def topological_order(nodes, edges):
    node_order = []
    seen = set()
    for node in nodes:
        if node not in seen:
            seen.add(node)
            node_order.append(node)

    adjacency = {node: [] for node in node_order}
    indegree = {node: 0 for node in node_order}
    edge_sets = {node: set() for node in node_order}

    for edge in edges:
        try:
            source, destination = edge
        except (TypeError, ValueError):
            raise ValueError("Each edge must contain exactly two nodes.") from None

        if source not in seen or destination not in seen:
            raise ValueError("Every edge endpoint must be in nodes.")

        if destination not in edge_sets[source]:
            edge_sets[source].add(destination)
            adjacency[source].append(destination)
            indegree[destination] += 1

    ready = [node for node in node_order if indegree[node] == 0]
    result = []
    index = 0

    while index < len(ready):
        node = ready[index]
        index += 1
        result.append(node)

        for destination in adjacency[node]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                ready.append(destination)

    if len(result) != len(node_order):
        raise ValueError("The graph contains a cycle.")

    return tuple(result)
